-- ============================================
-- 150 NURSING QUESTIONS - Full Question Bank
-- ============================================
-- Run this AFTER CREATE-TEST-TABLES.sql
-- Categories: Fundamentals (30), Cardiovascular (30), Neurological (30), 
--             Respiratory (30), Gastrointestinal (20), Endocrine (10)

-- Questions 11-30: Additional Fundamentals of Nursing
INSERT INTO test_questions (test_id, question_stem, options, correct_answers, is_multiple_choice, rationale, category, display_order) VALUES

('00000000-0000-0000-0000-000000000001', 'What is the correct technique for hand hygiene?', '[{"id":"a","text":"Rub hands for 10 seconds"},{"id":"b","text":"Rub hands for at least 15-20 seconds"},{"id":"c","text":"Rinse hands only"},{"id":"d","text":"Use soap without water"}]'::jsonb, ARRAY['b'], false, 'Proper hand hygiene requires rubbing hands with soap for 15-20 seconds.', 'Fundamentals of Nursing', 11),
('00000000-0000-0000-0000-000000000001', 'Which position is appropriate for a patient with dyspnea?', '[{"id":"a","text":"Supine"},{"id":"b","text":"Prone"},{"id":"c","text":"High Fowler''s"},{"id":"d","text":"Trendelenburg"}]'::jsonb, ARRAY['c'], false, 'High Fowler''s position (60-90 degrees) maximizes lung expansion for patients with breathing difficulty.', 'Fundamentals of Nursing', 12),
('00000000-0000-0000-0000-000000000001', 'What is the normal adult pulse range?', '[{"id":"a","text":"40-60 bpm"},{"id":"b","text":"60-100 bpm"},{"id":"c","text":"100-120 bpm"},{"id":"d","text":"120-140 bpm"}]'::jsonb, ARRAY['b'], false, 'Normal adult pulse is 60-100 beats per minute.', 'Fundamentals of Nursing', 13),
('00000000-0000-0000-0000-000000000001', 'Which are appropriate sites for IM injections? (Select all)', '[{"id":"a","text":"Deltoid"},{"id":"b","text":"Vastus lateralis"},{"id":"c","text":"Abdomen"},{"id":"d","text":"Ventrogluteal"},{"id":"e","text":"Dorsogluteal"}]'::jsonb, ARRAY['a','b','d'], true, 'IM injection sites include deltoid, vastus lateralis, and ventrogluteal muscles.', 'Fundamentals of Nursing', 14),
('00000000-0000-0000-0000-000000000001', 'What is the purpose of pain assessment?', '[{"id":"a","text":"To determine medication dosage"},{"id":"b","text":"To guide effective pain management interventions"},{"id":"c","text":"To document patient complaints"},{"id":"d","text":"To satisfy regulatory requirements"}]'::jsonb, ARRAY['b'], false, 'Pain assessment guides appropriate and effective pain management interventions.', 'Fundamentals of Nursing', 15),
('00000000-0000-0000-0000-000000000001', 'Normal adult blood pressure range is:', '[{"id":"a","text":"90/60 to 120/80 mmHg"},{"id":"b","text":"120/80 to 140/90 mmHg"},{"id":"c","text":"140/90 to 160/100 mmHg"},{"id":"d","text":"160/100 to 180/110 mmHg"}]'::jsonb, ARRAY['a'], false, 'Normal BP is <120/80 mmHg; optimal range is 90/60 to 120/80.', 'Fundamentals of Nursing', 16),
('00000000-0000-0000-0000-000000000001', 'Which actions prevent hospital-acquired infections? (Select all)', '[{"id":"a","text":"Hand hygiene"},{"id":"b","text":"Proper PPE use"},{"id":"c","text":"Aseptic technique"},{"id":"d","text":"Isolation precautions"},{"id":"e","text":"Environmental cleaning"}]'::jsonb, ARRAY['a','b','c','d','e'], true, 'All listed actions are essential infection control measures.', 'Fundamentals of Nursing', 17),
('00000000-0000-0000-0000-000000000001', 'What does the acronym RACE stand for in fire safety?', '[{"id":"a","text":"Run, Alert, Contain, Extinguish"},{"id":"b","text":"Rescue, Alarm, Confine, Extinguish"},{"id":"c","text":"Remove, Activate, Close, Evacuate"},{"id":"d","text":"Rescue, Assist, Call, Exit"}]'::jsonb, ARRAY['b'], false, 'RACE: Rescue patients, Alarm activation, Confine fire, Extinguish if safe.', 'Fundamentals of Nursing', 18),
('00000000-0000-0000-0000-000000000001', 'Which patient right is violated by discussing patient information in public areas?', '[{"id":"a","text":"Right to refuse treatment"},{"id":"b","text":"Right to privacy and confidentiality"},{"id":"c","text":"Right to informed consent"},{"id":"d","text":"Right to access medical records"}]'::jsonb, ARRAY['b'], false, 'Discussing patient information publicly violates privacy and confidentiality rights (HIPAA).', 'Fundamentals of Nursing', 19),
('00000000-0000-0000-0000-000000000001', 'What is the correct order for putting on PPE?', '[{"id":"a","text":"Gloves, gown, mask, goggles"},{"id":"b","text":"Gown, mask, goggles, gloves"},{"id":"c","text":"Mask, goggles, gown, gloves"},{"id":"d","text":"Goggles, mask, gloves, gown"}]'::jsonb, ARRAY['b'], false, 'Correct PPE donning: Gown, Mask/respirator, Goggles/face shield, Gloves.', 'Fundamentals of Nursing', 20),

('00000000-0000-0000-0000-000000000001', 'Normal body temperature range (oral) is:', '[{"id":"a","text":"35.0-36.5°C"},{"id":"b","text":"36.5-37.5°C"},{"id":"c","text":"37.5-38.5°C"},{"id":"d","text":"38.5-39.5°C"}]'::jsonb, ARRAY['b'], false, 'Normal oral temperature is 36.5-37.5°C (97.7-99.5°F).', 'Fundamentals of Nursing', 21),
('00000000-0000-0000-0000-000000000001', 'Which statement about informed consent is correct?', '[{"id":"a","text":"Nurses can obtain informed consent for surgery"},{"id":"b","text":"Implied consent applies to all medical procedures"},{"id":"c","text":"The physician performing the procedure obtains consent"},{"id":"d","text":"Consent is not needed for emergency treatments"}]'::jsonb, ARRAY['c'], false, 'The physician performing the procedure is responsible for obtaining informed consent.', 'Fundamentals of Nursing', 22),
('00000000-0000-0000-0000-000000000001', 'What is the proper technique for removing PPE?', '[{"id":"a","text":"Mask, goggles, gown, gloves"},{"id":"b","text":"Gloves, goggles, gown, mask"},{"id":"c","text":"Gown, gloves, goggles, mask"},{"id":"d","text":"Gloves, gown, goggles, mask"}]'::jsonb, ARRAY['b'], false, 'Correct PPE removal: Gloves, Goggles, Gown, Mask (most contaminated to least).', 'Fundamentals of Nursing', 23),
('00000000-0000-0000-0000-000000000001', 'Which factors affect medication absorption? (Select all)', '[{"id":"a","text":"Route of administration"},{"id":"b","text":"Blood flow to site"},{"id":"c","text":"Patient age"},{"id":"d","text":"Food in stomach"},{"id":"e","text":"Patient height"}]'::jsonb, ARRAY['a','b','c','d'], true, 'Route, blood flow, age, and food affect absorption; height does not significantly affect it.', 'Fundamentals of Nursing', 24),
('00000000-0000-0000-0000-000000000001', 'What is the purpose of the nursing care plan?', '[{"id":"a","text":"To satisfy insurance requirements"},{"id":"b","text":"To provide individualized patient-centered care"},{"id":"c","text":"To document all nursing tasks"},{"id":"d","text":"To establish hospital protocols"}]'::jsonb, ARRAY['b'], false, 'Care plans provide individualized, patient-centered nursing care based on assessment.', 'Fundamentals of Nursing', 25),
('00000000-0000-0000-0000-000000000001', 'Which oxygen delivery device provides the highest concentration?', '[{"id":"a","text":"Nasal cannula"},{"id":"b","text":"Simple face mask"},{"id":"c","text":"Non-rebreather mask"},{"id":"d","text":"Venturi mask"}]'::jsonb, ARRAY['c'], false, 'Non-rebreather masks can deliver 60-95% oxygen concentration with reservoir bag.', 'Fundamentals of Nursing', 26),
('00000000-0000-0000-0000-000000000001', 'What is the correct angle for subcutaneous injection?', '[{"id":"a","text":"15 degrees"},{"id":"b","text":"45-90 degrees"},{"id":"c","text":"90 degrees only"},{"id":"d","text":"180 degrees"}]'::jsonb, ARRAY['b'], false, 'Subcutaneous injections are given at 45-90 degrees depending on tissue depth.', 'Fundamentals of Nursing', 27),
('00000000-0000-0000-0000-000000000001', 'Which are signs of infection? (Select all)', '[{"id":"a","text":"Fever"},{"id":"b","text":"Redness"},{"id":"c","text":"Swelling"},{"id":"d","text":"Warmth"},{"id":"e","text":"Pain"}]'::jsonb, ARRAY['a','b','c','d','e'], true, 'Classic signs of infection: Fever, Redness, Swelling, Warmth, Pain.', 'Fundamentals of Nursing', 28),
('00000000-0000-0000-0000-000000000001', 'What is the priority action for a patient experiencing chest pain?', '[{"id":"a","text":"Document the pain assessment"},{"id":"b","text":"Notify the physician and obtain ECG"},{"id":"c","text":"Administer pain medication"},{"id":"d","text":"Encourage deep breathing"}]'::jsonb, ARRAY['b'], false, 'Chest pain requires immediate physician notification and ECG to rule out cardiac emergency.', 'Fundamentals of Nursing', 29),
('00000000-0000-0000-0000-000000000001', 'Which position prevents aspiration in an unconscious patient?', '[{"id":"a","text":"Supine"},{"id":"b","text":"High Fowler''s"},{"id":"c","text":"Side-lying (lateral)"},{"id":"d":"Prone"}]'::jsonb, ARRAY['c'], false, 'Side-lying position allows secretions to drain and prevents aspiration.', 'Fundamentals of Nursing', 30);

-- ============================================
-- CARDIOVASCULAR SYSTEM (30 questions: 31-60)
-- ============================================

INSERT INTO test_questions (test_id, question_stem, options, correct_answers, is_multiple_choice, rationale, category, display_order) VALUES

('00000000-0000-0000-0000-000000000001', 'What is the primary function of the heart?', '[{"id":"a","text":"Produce blood cells"},{"id":"b","text":"Pump blood throughout the body"},{"id":"c","text":"Filter blood"},{"id":"d","text":"Store oxygen"}]'::jsonb, ARRAY['b'], false, 'The heart''s primary function is to pump oxygenated blood to tissues and return deoxygenated blood to lungs.', 'Cardiovascular System', 31),
('00000000-0000-0000-0000-000000000001', 'Which are modifiable risk factors for coronary artery disease? (Select all)', '[{"id":"a","text":"Smoking"},{"id":"b","text":"Age"},{"id":"c","text":"Hypertension"},{"id":"d","text":"Family history"},{"id":"e","text":"Obesity"}]'::jsonb, ARRAY['a','c','e'], true, 'Modifiable risk factors: smoking, hypertension, obesity, diabetes, high cholesterol. Non-modifiable: age, gender, family history.', 'Cardiovascular System', 32),
('00000000-0000-0000-0000-000000000001', 'What does an elevated troponin level indicate?', '[{"id":"a","text":"Kidney damage"},{"id":"b","text":"Myocardial damage"},{"id":"c","text":"Liver dysfunction"},{"id":"d","text":"Respiratory distress"}]'::jsonb, ARRAY['b'], false, 'Elevated troponin indicates myocardial (heart muscle) damage, typically from MI.', 'Cardiovascular System', 33),
('00000000-0000-0000-0000-000000000001', 'A patient with heart failure should limit which nutrient?', '[{"id":"a","text":"Protein"},{"id":"b","text":"Sodium"},{"id":"c","text":"Fiber"},{"id":"d","text":"Calcium"}]'::jsonb, ARRAY['b'], false, 'Heart failure patients should limit sodium to reduce fluid retention and cardiac workload.', 'Cardiovascular System', 34),
('00000000-0000-0000-0000-000000000001', 'What is the normal range for total cholesterol?', '[{"id":"a","text":"<200 mg/dL"},{"id":"b","text":"200-239 mg/dL"},{"id":"c","text":"240-300 mg/dL"},{"id":"d","text":">300 mg/dL"}]'::jsonb, ARRAY['a'], false, 'Desirable total cholesterol is <200 mg/dL. 200-239 is borderline high.', 'Cardiovascular System', 35),
('00000000-0000-0000-0000-000000000001', 'Which medications are commonly prescribed for hypertension? (Select all)', '[{"id":"a","text":"ACE inhibitors"},{"id":"b","text":"Beta-blockers"},{"id":"c","text":"Antibiotics"},{"id":"d","text":"Diuretics"},{"id":"e","text":"Calcium channel blockers"}]'::jsonb, ARRAY['a','b','d','e'], true, 'Common antihypertensives: ACE inhibitors, beta-blockers, diuretics, calcium channel blockers.', 'Cardiovascular System', 36),
('00000000-0000-0000-0000-000000000001', 'What is the most common symptom of myocardial infarction?', '[{"id":"a","text":"Headache"},{"id":"b","text":"Chest pain or discomfort"},{"id":"c","text":"Leg pain"},{"id":"d","text":"Dizziness"}]'::jsonb, ARRAY['b'], false, 'Chest pain/pressure is the most common MI symptom, often radiating to arm, jaw, or back.', 'Cardiovascular System', 37),
('00000000-0000-0000-0000-000000000001', 'Which valve prevents backflow from the left ventricle to the left atrium?', '[{"id":"a","text":"Aortic valve"},{"id":"b","text":"Mitral valve"},{"id":"c","text":"Tricuspid valve"},{"id":"d":"Pulmonic valve"}]'::jsonb, ARRAY['b'], false, 'The mitral (bicuspid) valve prevents backflow from left ventricle to left atrium.', 'Cardiovascular System', 38),
('00000000-0000-0000-0000-000000000001', 'What is the primary purpose of anticoagulant therapy?', '[{"id":"a","text":"Lower blood pressure"},{"id":"b","text":"Prevent blood clot formation"},{"id":"c","text":"Increase heart rate"},{"id":"d":"Dissolve existing clots"}]'::jsonb, ARRAY['b'], false, 'Anticoagulants prevent new clot formation; thrombolytics dissolve existing clots.', 'Cardiovascular System', 39),
('00000000-0000-0000-0000-000000000001', 'Which ECG finding indicates atrial fibrillation?', '[{"id":"a","text":"Irregular rhythm with no P waves"},{"id":"b","text":"Regular rhythm with tall T waves"},{"id":"c","text":"Flat line"},{"id":"d":"Normal sinus rhythm"}]'::jsonb, ARRAY['a'], false, 'Atrial fibrillation shows irregularly irregular rhythm with absent P waves.', 'Cardiovascular System', 40);

