-- ============================================
-- NEUROLOGICAL SYSTEM (30 questions: 61-90)
-- ============================================

INSERT INTO test_questions (test_id, question_stem, options, correct_answers, is_multiple_choice, rationale, category, display_order) VALUES

('00000000-0000-0000-0000-000000000001', 'What is the primary function of the cerebellum?', '[{"id":"a","text":"Memory storage"},{"id":"b","text":"Coordination and balance"},{"id":"c","text":"Speech production"},{"id":"d":"Emotion regulation"}]'::jsonb, ARRAY['b'], false, 'The cerebellum coordinates voluntary movements and maintains balance and posture.', 'Neurological System', 61),
('00000000-0000-0000-0000-000000000001', 'Which are signs of increased intracranial pressure? (Select all)', '[{"id":"a","text":"Headache"},{"id":"b","text":"Vomiting"},{"id":"c","text":"Decreased level of consciousness"},{"id":"d","text":"Pupil changes"},{"id":"e","text":"Hypotension"}]'::jsonb, ARRAY['a','b','c','d'], true, 'ICP signs: headache, vomiting, decreased consciousness, pupil changes, bradycardia (not hypotension).', 'Neurological System', 62),
('00000000-0000-0000-0000-000000000001', 'What does the Glasgow Coma Scale assess?', '[{"id":"a","text":"Pain level"},{"id":"b","text":"Level of consciousness"},{"id":"c","text":"Pupil reactivity"},{"id":"d":"Blood pressure"}]'::jsonb, ARRAY['b'], false, 'GCS assesses level of consciousness using eye, verbal, and motor responses.', 'Neurological System', 63),
('00000000-0000-0000-0000-000000000001', 'Which cranial nerve controls vision?', '[{"id":"a","text":"Cranial nerve I (Olfactory)"},{"id":"b","text":"Cranial nerve II (Optic)"},{"id":"c","text":"Cranial nerve III (Oculomotor)"},{"id":"d":"Cranial nerve IV (Trochlear)"}]'::jsonb, ARRAY['b'], false, 'Cranial nerve II (Optic) transmits visual information from retina to brain.', 'Neurological System', 64),
('00000000-0000-0000-0000-000000000001', 'What is the most common cause of stroke?', '[{"id":"a","text":"Hemorrhage"},{"id":"b","text":"Ischemia (blood clot)"},{"id":"c","text":"Trauma"},{"id":"d":"Infection"}]'::jsonb, ARRAY['b'], false, 'Ischemic strokes (caused by blood clots) account for 87% of all strokes.', 'Neurological System', 65),
('00000000-0000-0000-0000-000000000001', 'Which assessment is priority for a stroke patient?', '[{"id":"a","text":"Bowel sounds"},{"id":"b","text":"Airway and breathing"},{"id":"c","text":"Skin integrity"},{"id":"d":"Emotional status"}]'::jsonb, ARRAY['b'], false, 'Airway/breathing assessment is always priority (ABCs) as stroke may impair airway protection.', 'Neurological System', 66),
('00000000-0000-0000-0000-000000000001', 'What does PERRLA stand for in pupil assessment?', '[{"id":"a","text":"Pupils Equal, Round, Reactive to Light and Accommodation"},{"id":"b","text":"Pupils Enlarged, Reactive, Light Adaptive"},{"id":"c","text":"Pupils Equal, Responsive, Left and Right Alert"},{"id":"d":"Pupils Examined, Responsive, Level, Adequate"}]'::jsonb, ARRAY['a'], false, 'PERRLA: Pupils Equal, Round, Reactive to Light and Accommodation.', 'Neurological System', 67),
('00000000-0000-0000-0000-000000000001', 'Which medication is given to prevent seizures?', '[{"id":"a","text":"Anticoagulants"},{"id":"b","text":"Anticonvulsants"},{"id":"c","text":"Antibiotics"},{"id":"d":"Antihypertensives"}]'::jsonb, ARRAY['b'], false, 'Anticonvulsants (e.g., phenytoin, levetiracetam) prevent or control seizures.', 'Neurological System', 68),
('00000000-0000-0000-0000-000000000001', 'What is the normal intracranial pressure range?', '[{"id":"a","text":"0-5 mmHg"},{"id":"b","text":"5-15 mmHg"},{"id":"c","text":"15-25 mmHg"},{"id":"d":"25-35 mmHg"}]'::jsonb, ARRAY['b'], false, 'Normal ICP is 5-15 mmHg in adults. >20 mmHg indicates increased ICP.', 'Neurological System', 69),
('00000000-0000-0000-0000-000000000001', 'Which action is appropriate during a seizure? (Select all)', '[{"id":"a","text":"Protect from injury"},{"id":"b","text":"Time the seizure"},{"id":"c","text":"Insert something in mouth"},{"id":"d","text":"Turn to side if possible"},{"id":"e","text":"Loosen tight clothing"}]'::jsonb, ARRAY['a','b','d','e'], true, 'During seizure: protect from injury, time it, position on side, loosen clothing. Never insert objects in mouth.', 'Neurological System', 70);

-- ============================================
-- RESPIRATORY SYSTEM (30 questions: 91-120)
-- ============================================

INSERT INTO test_questions (test_id, question_stem, options, correct_answers, is_multiple_choice, rationale, category, display_order) VALUES

('00000000-0000-0000-0000-000000000001', 'What is the primary function of the alveoli?', '[{"id":"a","text":"Produce mucus"},{"id":"b","text":"Gas exchange"},{"id":"c","text":"Filter air"},{"id":"d":"Warm air"}]'::jsonb, ARRAY['b'], false, 'Alveoli are tiny air sacs where oxygen and carbon dioxide exchange occurs.', 'Respiratory System', 91),
('00000000-0000-0000-0000-000000000001', 'Which are signs of respiratory distress? (Select all)', '[{"id":"a","text":"Tachypnea"},{"id":"b","text":"Use of accessory muscles"},{"id":"c","text":"Cyanosis"},{"id":"d","text":"Pink skin"},{"id":"e","text":"Dyspnea"}]'::jsonb, ARRAY['a','b','c','e'], true, 'Respiratory distress signs: tachypnea, accessory muscle use, cyanosis, dyspnea, decreased O2 saturation.', 'Respiratory System', 92),
('00000000-0000-0000-0000-000000000001', 'What is normal oxygen saturation range?', '[{"id":"a","text":"85-90%"},{"id":"b","text":"91-94%"},{"id":"c","text":"95-100%"},{"id":"d":"75-85%"}]'::jsonb, ARRAY['c'], false, 'Normal SpO2 is 95-100%. <90% indicates hypoxemia requiring intervention.', 'Respiratory System', 93),
('00000000-0000-0000-0000-000000000001', 'Which position best facilitates breathing?', '[{"id":"a","text":"Supine"},{"id":"b","text":"Fowler''s or Semi-Fowler''s"},{"id":"c","text":"Prone"},{"id":"d":"Trendelenburg"}]'::jsonb, ARRAY['b'], false, 'Fowler''s/Semi-Fowler''s positions promote lung expansion and ease breathing.', 'Respiratory System', 94),
('00000000-0000-0000-0000-000000000001', 'What is the purpose of incentive spirometry?', '[{"id":"a","text":"Measure blood pressure"},{"id":"b","text":"Encourage deep breathing and prevent atelectasis"},{"id":"c","text":"Deliver medication"},{"id":"d":"Measure heart rate"}]'::jsonb, ARRAY['b'], false, 'Incentive spirometry promotes deep breathing, lung expansion, and prevents atelectasis post-op.', 'Respiratory System', 95),
('00000000-0000-0000-0000-000000000001', 'Which condition is characterized by airway inflammation and bronchospasm?', '[{"id":"a","text":"Pneumonia"},{"id":"b","text":"Asthma"},{"id":"c","text":"Tuberculosis"},{"id":"d":"Lung cancer"}]'::jsonb, ARRAY['b'], false, 'Asthma is characterized by airway inflammation, hyperresponsiveness, and bronchospasm.', 'Respiratory System', 96),
('00000000-0000-0000-0000-000000000001', 'What is the priority intervention for hypoxemia?', '[{"id":"a","text":"Administer oxygen"},{"id":"b","text":"Position patient"},{"id":"c","text":"Document findings"},{"id":"d":"Call family"}]'::jsonb, ARRAY['a'], false, 'Administering oxygen is priority for hypoxemia to restore adequate oxygenation.', 'Respiratory System', 97),
('00000000-0000-0000-0000-000000000001', 'Which diagnostic test visualizes lung tissue?', '[{"id":"a","text":"ECG"},{"id":"b","text":"Chest X-ray"},{"id":"c","text":"CT scan"},{"id":"d":"Both b and c"}]'::jsonb, ARRAY['d'], false, 'Chest X-ray and CT scan visualize lung tissue, pneumonia, masses, and structural abnormalities.', 'Respiratory System', 98),
('00000000-0000-0000-0000-000000000001', 'What is the hallmark sign of pneumonia?', '[{"id":"a","text":"Productive cough with purulent sputum"},{"id":"b","text":"Dry cough"},{"id":"c","text":"Wheezing"},{"id":"d":"Hemoptysis"}]'::jsonb, ARRAY['a'], false, 'Pneumonia typically presents with productive cough, purulent sputum, fever, and dyspnea.', 'Respiratory System', 99),
('00000000-0000-0000-0000-000000000001', 'Which medications dilate airways? (Select all)', '[{"id":"a","text":"Bronchodilators"},{"id":"b","text":"Antibiotics"},{"id":"c","text":"Beta-2 agonists"},{"id":"d":"Anticholinergics"},{"id":"e","text":"Anticoagulants"}]'::jsonb, ARRAY['a','c','d'], true, 'Bronchodilators (beta-2 agonists, anticholinergics) relax airway smooth muscle and improve airflow.', 'Respiratory System', 100);

-- ============================================
-- GASTROINTESTINAL SYSTEM (20 questions: 121-140)
-- ============================================

INSERT INTO test_questions (test_id, question_stem, options, correct_answers, is_multiple_choice, rationale, category, display_order) VALUES

('00000000-0000-0000-0000-000000000001', 'What is the primary function of the stomach?', '[{"id":"a","text":"Absorb nutrients"},{"id":"b","text":"Begin protein digestion"},{"id":"c","text":"Produce bile"},{"id":"d":"Store feces"}]'::jsonb, ARRAY['b'], false, 'The stomach begins protein digestion using pepsin and hydrochloric acid.', 'Gastrointestinal System', 121),
('00000000-0000-0000-0000-000000000001', 'Which are signs of gastrointestinal bleeding? (Select all)', '[{"id":"a","text":"Melena (black tarry stools)"},{"id":"b","text":"Hematemesis (vomiting blood)"},{"id":"c","text":"Pale skin"},{"id":"d","text":"Tachycardia"},{"id":"e","text":"Hypertension"}]'::jsonb, ARRAY['a','b','c','d'], true, 'GI bleeding signs: melena, hematemesis, anemia symptoms (pale skin, tachycardia, hypotension).', 'Gastrointestinal System', 122),
('00000000-0000-0000-0000-000000000001', 'What is the primary treatment for peptic ulcer disease?', '[{"id":"a","text":"Surgery"},{"id":"b","text":"Proton pump inhibitors and antibiotics"},{"id":"c","text":"High-fat diet"},{"id":"d":"Bed rest"}]'::jsonb, ARRAY['b'], false, 'PUD treatment: PPIs to reduce acid, antibiotics if H. pylori positive, lifestyle modifications.', 'Gastrointestinal System', 123),
('00000000-0000-0000-0000-000000000001', 'Which organ produces bile?', '[{"id":"a","text":"Pancreas"},{"id":"b","text":"Stomach"},{"id":"c","text":"Liver"},{"id":"d":"Gallbladder"}]'::jsonb, ARRAY['c'], false, 'The liver produces bile; gallbladder stores and concentrates it.', 'Gastrointestinal System', 124),
('00000000-0000-0000-0000-000000000001', 'What is the Bristol Stool Scale used for?', '[{"id":"a","text":"Measuring urine output"},{"id":"b","text":"Classifying stool consistency"},{"id":"c","text":"Assessing pain"},{"id":"d":"Measuring blood pressure"}]'::jsonb, ARRAY['b'], false, 'Bristol Stool Scale classifies stool consistency from Type 1 (hard) to Type 7 (liquid).', 'Gastrointestinal System', 125),
('00000000-0000-0000-0000-000000000001', 'Which condition requires immediate surgical intervention?', '[{"id":"a","text":"Appendicitis"},{"id":"b","text":"GERD"},{"id":"c","text":"Constipation"},{"id":"d":"Gastritis"}]'::jsonb, ARRAY['a'], false, 'Acute appendicitis requires emergency appendectomy to prevent rupture and peritonitis.', 'Gastrointestinal System', 126),
('00000000-0000-0000-0000-000000000001', 'What is the primary symptom of bowel obstruction?', '[{"id":"a","text":"Diarrhea"},{"id":"b","text":"Abdominal distension and cramping"},{"id":"c","text":"Weight gain"},{"id":"d":"Increased appetite"}]'::jsonb, ARRAY['b'], false, 'Bowel obstruction causes abdominal distension, cramping, vomiting, and inability to pass gas/stool.', 'Gastrointestinal System', 127),
('00000000-0000-0000-0000-000000000001', 'Which dietary modification helps manage GERD?', '[{"id":"a","text":"Eat large meals"},{"id":"b","text":"Avoid trigger foods and eat smaller meals"},{"id":"c","text":"Lie down after eating"},{"id":"d":"Increase spicy foods"}]'::jsonb, ARRAY['b'], false, 'GERD management: avoid triggers (caffeine, alcohol, spicy foods), smaller meals, stay upright after eating.', 'Gastrointestinal System', 128),
('00000000-0000-0000-0000-000000000001', 'What is the purpose of a nasogastric tube?', '[{"id":"a","text":"Provide oxygen"},{"id":"b","text":"Decompress stomach or provide nutrition"},{"id":"c","text":"Measure blood pressure"},{"id":"d":"Deliver IV medications"}]'::jsonb, ARRAY['b'], false, 'NG tube decompresses stomach (removes gas/fluid) or provides enteral nutrition.', 'Gastrointestinal System', 129),
('00000000-0000-0000-0000-000000000001', 'Which lab value indicates liver function?', '[{"id":"a","text":"Creatinine"},{"id":"b","text":"ALT and AST"},{"id":"c","text":"Hemoglobin"},{"id":"d":"White blood cells"}]'::jsonb, ARRAY['b'], false, 'ALT and AST (liver enzymes) indicate liver function; elevated levels suggest liver damage.', 'Gastrointestinal System', 130);

-- ============================================
-- ENDOCRINE SYSTEM (10 questions: 141-150)
-- ============================================

INSERT INTO test_questions (test_id, question_stem, options, correct_answers, is_multiple_choice, rationale, category, display_order) VALUES

('00000000-0000-0000-0000-000000000001', 'What hormone regulates blood glucose?', '[{"id":"a","text":"Thyroid hormone"},{"id":"b","text":"Insulin"},{"id":"c","text":"Cortisol"},{"id":"d":"Growth hormone"}]'::jsonb, ARRAY['b'], false, 'Insulin (from pancreas) lowers blood glucose by facilitating cellular uptake.', 'Endocrine System', 141),
('00000000-0000-0000-0000-000000000001', 'Which are symptoms of hyperglycemia? (Select all)', '[{"id":"a","text":"Polyuria (frequent urination)"},{"id":"b","text":"Polydipsia (increased thirst)"},{"id":"c","text":"Polyphagia (increased hunger)"},{"id":"d","text":"Tremors"},{"id":"e","text":"Blurred vision"}]'::jsonb, ARRAY['a','b','c','e'], true, 'Hyperglycemia symptoms: 3 Ps (polyuria, polydipsia, polyphagia), blurred vision, fatigue.', 'Endocrine System', 142),
('00000000-0000-0000-0000-000000000001', 'What is the target fasting blood glucose for diabetics?', '[{"id":"a","text":"70-130 mg/dL"},{"id":"b","text":"140-180 mg/dL"},{"id":"c","text":"200-250 mg/dL"},{"id":"d":"<70 mg/dL"}]'::jsonb, ARRAY['a'], false, 'ADA recommends fasting blood glucose 70-130 mg/dL for most diabetics.', 'Endocrine System', 143),
('00000000-0000-0000-0000-000000000001', 'Which gland regulates metabolism?', '[{"id":"a","text":"Pancreas"},{"id":"b","text":"Thyroid"},{"id":"c","text":"Adrenal"},{"id":"d":"Pituitary"}]'::jsonb, ARRAY['b'], false, 'The thyroid gland produces hormones (T3, T4) that regulate metabolism.', 'Endocrine System', 144),
('00000000-0000-0000-0000-000000000001', 'What is the priority treatment for hypoglycemia?', '[{"id":"a","text":"Administer insulin"},{"id":"b","text":"Give 15g simple carbohydrate"},{"id":"c","text":"Restrict food intake"},{"id":"d":"Increase exercise"}]'::jsonb, ARRAY['b'], false, 'Hypoglycemia treatment: 15g fast-acting carbs (juice, glucose tablets), recheck in 15 min.', 'Endocrine System', 145),
('00000000-0000-0000-0000-000000000001', 'Which condition results from insulin deficiency?', '[{"id":"a","text":"Hyperthyroidism"},{"id":"b","text":"Diabetes mellitus"},{"id":"c","text":"Cushing''s syndrome"},{"id":"d":"Addison''s disease"}]'::jsonb, ARRAY['b'], false, 'Diabetes mellitus results from insulin deficiency (Type 1) or resistance (Type 2).', 'Endocrine System', 146),
('00000000-0000-0000-0000-000000000001', 'What is HbA1c used to measure?', '[{"id":"a","text":"Current blood glucose"},{"id":"b","text":"Average blood glucose over 2-3 months"},{"id":"c","text":"Liver function"},{"id":"d":"Kidney function"}]'::jsonb, ARRAY['b'], false, 'HbA1c reflects average blood glucose over past 2-3 months; goal <7% for most diabetics.', 'Endocrine System', 147),
('00000000-0000-0000-0000-000000000001', 'Which hormone is produced by the adrenal glands?', '[{"id":"a","text":"Insulin"},{"id":"b","text":"Thyroxine"},{"id":"c","text":"Cortisol"},{"id":"d":"Melatonin"}]'::jsonb, ARRAY['c'], false, 'Adrenal glands produce cortisol (stress hormone), aldosterone, and epinephrine.', 'Endocrine System', 148),
('00000000-0000-0000-0000-000000000001', 'What are signs of hypothyroidism? (Select all)', '[{"id":"a","text":"Fatigue"},{"id":"b","text":"Weight gain"},{"id":"c","text":"Cold intolerance"},{"id":"d","text":"Tachycardia"},{"id":"e","text":"Constipation"}]'::jsonb, ARRAY['a','b','c','e'], true, 'Hypothyroidism symptoms: fatigue, weight gain, cold intolerance, constipation, bradycardia (not tachycardia).', 'Endocrine System', 149),
('00000000-0000-0000-0000-000000000001', 'What is diabetic ketoacidosis (DKA)?', '[{"id":"a","text":"Low blood glucose emergency"},{"id":"b","text":"High blood glucose with ketones and acidosis"},{"id":"c","text":"Normal blood glucose response"},{"id":"d":"Thyroid crisis"}]'::jsonb, ARRAY['b'], false, 'DKA is life-threatening complication of Type 1 diabetes: severe hyperglycemia, ketones, acidosis.', 'Endocrine System', 150);

